package e2e

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// std/deflate on the native backends: the 60 KB corpus the example test
// decodes under the interpreter, gunzipped by x86-64 and arm64 binaries,
// checked by length and CRC-32. The example test (TestRunnerDeflateExamplePasses)
// holds the format's cases; this pins that the decoder's bit and array
// work compiles the same way on both ISAs.
func TestDeflateGunzipNative(t *testing.T) {
	bin := buildFernCLI(t)
	src := `import "std/deflate";
import "std/hex";
import "std/hash";
import "core/int";

function main(): i32 {
    match (deflate.gunzip(hex.hex_decode("` + deflateCorpusGzipHex + `"), 1048576)) {
        Ok(out) => {
            if (hash.crc32_new().update_bytes(out[:]).finish() == 524053769 as u32) {
                print(int.int_to_string(out.len()) + " crc-ok");
                return 0;
            }
            print(int.int_to_string(out.len()) + " crc-bad");
            return 1;
        },
        Err(e) => {
            print(e.message());
            return 1;
        }
    }
    return 2;
}
`
	dir := t.TempDir()
	srcPath := filepath.Join(dir, "gunzip.fern")
	if err := os.WriteFile(srcPath, []byte(src), 0o644); err != nil {
		t.Fatalf("write src: %v", err)
	}
	for _, be := range nativeBackends() {
		be := be
		t.Run(be.target, func(t *testing.T) {
			qemu := be.qemu(t)
			out := filepath.Join(dir, be.target+"_gunzip.bin")
			if o, err := exec.Command(bin, "-target", be.target, "-o", out, srcPath).CombinedOutput(); err != nil {
				t.Fatalf("build failed: %v\n%s", err, o)
			}
			cmd := be.run(qemu, out)
			var stdout bytes.Buffer
			cmd.Stdout = &stdout
			_ = cmd.Run()
			if got := strings.TrimSpace(stdout.String()); got != "70890 crc-ok" || cmd.ProcessState.ExitCode() != 0 {
				t.Fatalf("exit %d, stdout %q, want \"70890 crc-ok\"", cmd.ProcessState.ExitCode(), got)
			}
		})
	}
}

// deflateCorpusGzipHex is the gzip of 3000 numbered lines, the same
// vector tests/stdlib/deflate_test.fern decodes.
const deflateCorpusGzipHex = ""
